// MT2009_PLUS_GMPANEL_POINT_BONUS_V1 (point): zgloszenie #25 (8 Nov 2026) - the panel (interfacemodule.py
// GMPanelPointItems) sends a POINT_* number as 1000 + point: every bonus of this engine, the 6th/7th ones too
// (193-318 - two-byte since wideattr, so the result is a WORD); a classic number (1-91, an older client) still goes
// through the table below.
static WORD GMPanelClassicApplyToPoint(int classicApply)

{

	if (classicApply >= 1000)
	{
		const int iPoint = classicApply - 1000;
		return (iPoint > POINT_NONE && iPoint < POINT_MAX_NUM) ? (WORD) iPoint : (WORD) POINT_NONE;
	}
